input:enabled:
descendant-or-self::input[
        (
            (
                name(.) = 'fieldset' or
                name(.) = 'optgroup'
            )
            and not(@disabled)
        ) or (
            (
                name(.) = 'input' or
                name(.) = 'button' or
                name(.) = 'select' or
                name(.) = 'textarea'
            )
            and not(@disabled) and not(ancestor::fieldset[@disabled] and not(count(ancestor::legend | ancestor::fieldset[@disabled]/legend[1]) < count(ancestor::legend) + count(ancestor::fieldset[@disabled]/legend[1])))
        ) or (
            name(.) = 'option' and not(
                @disabled or ancestor::optgroup[@disabled]
            )
        )
        ]
